// 1. Tenta buscar os dados do Webhook. Se não houver, usa os clientes de exemplo para testes.
let clientes = [];
try {
  const dadosWebhook = $('Webhook - Clientes').first().json;
  // Verifica se os clientes vieram numa propriedade específica ou se o objeto já é a lista
  clientes = dadosWebhook.clientes || (Array.isArray(dadosWebhook) ? dadosWebhook : []);
} catch (e) {
  clientes = [];
}

// Se o webhook estiver vazio, usamos estes dados de teste para o fluxo não travar
if (!clientes || clientes.length === 0) {
  clientes = [
    { nome: "Ana Silva", email: "ana@email.com", saldo: "R$ 12.500,00", perfil: "Conservador" },
    { nome: "Bruno Lima", email: "bruno@email.com", saldo: "R$ 3.200,00", perfil: "Moderado" },
    { nome: "Carla Souza", email: "carla@email.com", saldo: "R$ 28.900,00", perfil: "Arrojado" },
    { nome: "Daniel Oliveira", email: "daniel@email.com", saldo: "R$ 850,00", perfil: "Conservador" },
    { nome: "Elena Rodrigues", email: "elena@email.com", saldo: "R$ 45.000,00", perfil: "Arrojado" }
  ];
}

// 2. Pega o conteúdo do CSV do nó HTTP Request
const csvItem = $('HTTP Request - BuscarInvestimento').first().json;
const csvText = csvItem.data || csvItem.body || csvItem.text || "";

// Função para converter o texto CSV em array de objetos JSON
function parseCSV(text) {
  const lines = text.trim().split('\n');
  if (lines.length === 0) return [];
  const headers = lines[0].split(',').map(h => h.trim());

  const result = [];
  for (let i = 1; i < lines.length; i++) {
    const currentLine = lines[i].split(',').map(val => val.trim());
    if (currentLine.length === headers.length) {
      const obj = {};
      for (let j = 0; j < headers.length; j++) {
        obj[headers[j]] = currentLine[j];
      }
      result.push(obj);
    }
  }
  return result;
}

const todosInvestimentos = parseCSV(csvText);

// 3. Mapeia cada cliente e filtra APENAS os investimentos do seu perfil
return clientes.map(cliente => {
  const perfilCliente = cliente.perfil ? cliente.perfil.trim() : "";

  const investimentosFiltrados = todosInvestimentos.filter(
    inv => inv.perfil && inv.perfil.trim().toLowerCase() === perfilCliente.toLowerCase()
  );

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: perfilCliente,
      investimentosCompativeis: investimentosFiltrados
    }
  };
});

