return $input.all().map(item => {
  let parsedContent;
  try {
    // Remove crases de markdown e espaços extras caso a IA mande ```json ... ```
    let rawOutput = item.json.output.replace(/```json/g, '').replace(/```/g, '').trim();
    parsedContent = JSON.parse(rawOutput);
  } catch (e) {
    // Se ainda assim falhar, tenta extrair o texto bruto para não perder o e-mail
    parsedContent = { 
      assunto: "Sua Recomendação de Investimento", 
      body_html: item.json.output 
    };
  }

  return {
    json: {
      ...item.json,
      assunto: parsedContent.assunto,
      body_html: parsedContent.body_html
    }
  };
});
